int main() {
    /* Test the truncation issue */
    char proxy_env[20];

    /* Test with various scheme lengths */
    const char *schemes[] = {
        "http",           /* 4 chars - fits */
        "https",          /* 5 chars - fits */
        "ftp",            /* 3 chars - fits */
        "verylongscheme", /* 14 chars - 14 + 6 = 20, fits exactly */
        "verylongschemen", /* 15 chars - 15 + 6 = 21, truncates */
        "extremelylongprotocolname", /* 25 chars - truncates */
        "thisisareallylongschemename", /* 29 chars - truncates */
        NULL
    };

    printf("Testing proxy_env buffer truncation (buffer size: 20)\n");
    printf("Format: \"%%s_proxy\" adds 6 chars (\"_proxy\" + NUL)\n");
    printf("Max scheme length that fits: 20 - 6 = 14 chars\n\n");

    for (int i = 0; schemes[i]; i++) {
        const char *scheme = schemes[i];
        int scheme_len = strlen(scheme);
        int expected_len = scheme_len + 6; /* scheme + "_proxy" + NUL */

        curl_msnprintf(proxy_env, sizeof(proxy_env), "%s_proxy", scheme);
        int actual_len = strlen(proxy_env);

        printf("Scheme: %-30s (len=%2d) -> proxy_env: %-25s (len=%2d) %s\n",
               scheme, scheme_len, proxy_env, actual_len,
               expected_len > 20 ? "*** TRUNCATED ***" : "OK");
    }

    printf("\n--- Demonstrating the bug ---\n");
    printf("If scheme is \"verylongschemename\" (20 chars):\n");
    curl_msnprintf(proxy_env, sizeof(proxy_env), "%s_proxy", "verylongschemename");
    printf("  proxy_env = \"%s\" (len=%zu)\n", proxy_env, strlen(proxy_env));
    printf("  Expected: \"verylongschemename_proxy\" (26 chars)\n");
    printf("  Actual:   \"%s\" (truncated to 19 chars + NUL)\n", proxy_env);
    printf("\nThis means curl will look for env var \"verylongschemen_proxy\" instead of \"verylongschemename_proxy\"\n");

    return 0;
}

