// Test program to reproduce the wssl_strerror buffer overflow
// This simulates the release build behavior where DEBUGASSERT is a no-op

#include <stdio.h>
#include <string.h>
#include <assert.h>

// Simulate DEBUGASSERT behavior in release build (no-op)
#define DEBUGASSERT(x) do { } while(0)

// Copy of the vulnerable function from lib/vtls/wolfssl.c
static char *wssl_strerror(unsigned long error, char *buf, unsigned long size)
{
    DEBUGASSERT(size > 40);
    *buf = '\0';

    // Simulate wolfSSL_ERR_error_string_n writing nothing (error case)
    // In real code, this would be: wolfSSL_ERR_error_string_n(error, buf, size);
    // But we simulate it writing nothing to trigger the fallback

    if(!*buf) {
        const char *msg = error ? "Unknown error" : "No error";
        /* the string fits because the assert above assures this */
        strcpy(buf, msg);
    }

    return buf;
}

int main() {
    // Test 1: Buffer too small for "Unknown error" (13 bytes including NUL)
    printf("Test 1: Buffer size 12 (too small for 'Unknown error')\n");
    char small_buffer[12];
    wssl_strerror(1, small_buffer, 12); // This will overflow in release build
    printf("Result: %s\n", small_buffer);

    // Test 2: Buffer exactly 13 bytes (minimum for "Unknown error")
    printf("\nTest 2: Buffer size 13 (exact fit for 'Unknown error')\n");
    char exact_buffer[13];
    wssl_strerror(1, exact_buffer, 13);
    printf("Result: %s\n", exact_buffer);

    // Test 3: Buffer size 7 (too small for "No error" which needs 7 bytes)
    printf("\nTest 3: Buffer size 6 (too small for 'No error')\n");
    char tiny_buffer[6];
    wssl_strerror(0, tiny_buffer, 6); // This will overflow
    printf("Result: %s\n", tiny_buffer);

    return 0;
}

